INSERT INTO dictation_progress (learner, direction, level, source, current_word_id, answered, hinted, asked_ids, asked_count, right_count, round_start) VALUES (:learner, :direction, :level, :source, 0, 1, 0, '', 0, 0, (SELECT COALESCE(MAX(id), 0) FROM dictation_attempt WHERE learner = :learner)) ON CONFLICT(learner) DO UPDATE SET direction = excluded.direction, level = excluded.level, source = excluded.source
